mapper.sql:
where 1=1

		and cdrg_llave = #{llaveTabla}


		and cdrg_estado = #{estado}


		and cdrg_documentoprincipal = #{documentoPrincipal}


		and cdrg_documentomodificador = #{documentoModificador}


		and ddrg_fecha >= #{fechaMin}


		and ddrg_fecha  <   #{fechaMax}


		and cdrg_estadoinicial = #{estadoInicial}


		and cdrg_estadofinal = #{estadoFinal}


		and cdrg_usuario = #{usuario}


		and cdrg_ubicacion = #{ubicacion}


		and cdrg_valores = #{valores}


		and ddrg_cierre >= #{cierreMin}


		and ddrg_cierre  <   #{cierreMax}


		and cdrg_nombre = #{nombre}

mapper.select:
select cdrg_llave as llaveTabla ,cdrg_documentoprincipal as documentoPrincipal ,cdrg_documentomodificador as documentoModificador ,ddrg_fecha as fecha ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cdrg_estadoinicial) as estadoInicial ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cdrg_estadofinal) as estadoFinal ,cdrg_estado as estado ,cdrg_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cdrg_usuario) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cdrg_usuario) as responsableImagen ,modifica.cpdv_nombre as modificadorNombre ,movimiento_descripcion(modifica.cpdv_llave) as comentario ,modifica.cpdv_plantilla as plantilla ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave = modifica.cpdv_plantilla) as plantillaNombre ,(select mpvd_saldo from pedidoventadinero_pvdp where cpvd_llave = cdrg_valores) as saldo ,(select mpvd_valortotal from pedidoventadinero_pvdp where cpvd_llave = cdrg_valores) as total ,cdrg_ubicacion as ubicacion ,movimiento_descripcion(cdrg_ubicacion) as ubicacionNombre ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave = (select cpdv_plantilla from pedidoventa_pdvp where cpdv_llave = cdrg_ubicacion)) as ubicacionPlantilla ,cdrg_nombre as nombre from documentorelaciongestor_drgpz_drg_documentorelaciongestor left join pedidoventa_pdvp modifica on (cpdv_llave = cdrg_documentomodificador) where cdrg_documentoprincipal = #{dto.documentoPrincipal} and cdrg_usuario != #{usuarioAutomatico}
union select cact_llave as llaveTabla ,cact_llave as documentoPrincipal ,null as documentoModificador ,dact_fecharegistro as fecha ,null as estadoInicial ,null as estadoFinal ,null as estado ,cact_usuarioregistro as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cact_usuarioregistro) as responsable ,null as responsableImagen ,null as modificadorNombre ,cact_comentario as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,(select 'Asignado a ' || cusr_nombre from usuario_usrp where cusr_llave = cact_responsable) as nombre from actividad_actp where cact_documento = #{dto.documentoPrincipal} union select cpva_llave as llaveTabla ,cpva_llave as documentoPrincipal ,null as documentoModificador ,dpva_fecha as fecha ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cpva_estadoinicial) as estadoInicial ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cpva_estadofinal) as estadoFinal ,null as estado ,cpva_responsable as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cpva_responsable) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cpva_responsable) as responsableImagen ,null as modificadorNombre ,cpva_motivo as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,null as nombre from pedidoventaajuste_pvap where cpva_documento = #{dto.documentoPrincipal}
union select cmsj_llave as llaveTabla ,cmsj_documento as documentoPrincipal ,null as documentoModificador ,dmsj_fecha as fecha ,cmsj_correo as estadoInicial ,null as estadoFinal ,null as estado ,cmsj_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cmsj_usuario) as responsable ,null as responsableImagen ,null as modificadorNombre ,cmsj_titulo as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,CASE WHEN dmsj_correoenviado IS NULL THEN 'Mensaje sin correo enviado' ELSE CASE WHEN cmsj_correoerror IS NULL THEN 'Mensaje enviado el ' || to_char(dmsj_correoenviado, 'yyyy-mm-dd HH24:MI:SS') ELSE to_char(dmsj_correoenviado, 'yyyy-mm-dd HH24:MI:SS') || cmsj_correoerror END END as nombre from mensaje_msjp where cmsj_documento = #{dto.documentoPrincipal}
union select ctpi_llave as llaveTabla ,cdpr_documento as documentoPrincipal ,null as documentoModificador ,dtpi_fecha as fecha ,(select movimiento_descripcion(cbod_documento) from bodega_bodp where cbod_llave = ctpi_bodega) as estadoInicial ,null as estadoFinal ,null as estado ,ctpi_responsable as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = ctpi_responsable) as responsable ,null as responsableImagen ,null as modificadorNombre ,('[ Inician : ' || mtpi_cantidadinicial || '] Se mueve inventario de: ' || mtpi_cantidad || ' => Terminan : ' || mtpi_cantidadfinal) as comentario ,null as plantilla ,null as plantillaNombre ,null as saldo ,null as total ,null as ubicacion ,null as ubicacionNombre ,null as ubicacionPlantilla ,(select movimiento_descripcion(cpro_documento) from producto_prop where cpro_llave = ctpi_producto) as nombre from trazabilidadproductoinventario_tpip inner join deduccionproducto_dprp on (cdpr_llave = ctpi_deduccionproducto ) where cdpr_documento = #{dto.documentoPrincipal}
order by fecha desc LIMIT #{dto.paginacionRegistroFinal} OFFSET #{dto.paginacionRegistroInicial}
